from pathlib import Path
from PIL import Image
import hashlib,json
p=Path(__file__).resolve().parent;r=p.parents[1]
rows=json.loads((p/'dense-cycle-v10-prompt-index.json').read_bytes())['poses']
crop=[80,96,176,192];rect=[88,116,151,161]
standing=r/'character/james-west-master-carry-v1/local-v3-carry-pose.png'
for i,neighbors,problem in [(3,(2,4),'Case hangs lower and is taller than both adjacent poses. Raise it about2-3 native pixels and restore adjacent panel height.'),(30,(29,31),'Case sits higher than both adjacent poses. Lower it about2 native pixels while retaining the same rigid panel height.'),(46,(44,47),'Case drops several pixels and near hand/cuff disconnects from its neighbour carry height. Raise the case and connected gloves about3-4 native pixels.')]:
 name=f'walk{i:02d}-contact-v13';base=p/rows[i]['source'];files=[base,standing,Path(__file__),p/'package_key.py',p/'package_pose.py',p/'dense-cycle-v10-prompt-index.json']
 refs=[]
 for f,suffix in [(base,'target'),(standing,'standing-reference')]+[(p/rows[j]['source'],f'neighbour-{j:02d}') for j in neighbors]:
  target=p/f'{name}-{suffix}.png';Image.open(f).convert('RGBA').crop(crop).resize((384,384),Image.Resampling.LANCZOS).save(target);refs.append(target);files.extend([f,target])
 prompt=f'''Edit image1 only: James West carrying walk phase{i}, one fixed96x96 native crop enlarged4x. Preserve original camera, native body density and transparent alpha. Image2 is the provisional standing carry reference for physical case proportions and neutral matte material; images3 and4 are actual nearby chronological carrying poses for position and hand contact. {problem} Rebuild ONE coherent rigid graphite rectangular case and both connected gripping hands to sit continuously between images3/4. Approximate native case top130-132 and bottom150-152 in the full256 canvas; do not add bob or tilt unrelated to those neighbours. Preserve a consistent modest bevel/depth, flat graphite front panel, four small dull silver corner latches matching image2, far glove gripping LEFT edge and near glove supporting RIGHT edge, natural fingertips and wrist attached to existing silver cuff. Do not stretch the box taller, change its panel width unpredictably, use giant square latches, detach a hand, cut fingers through the box or add a black hole. Match image1 original soft detailed game-sprite material, not enlarged pixel outlines or glossy rendered plastic. Keep all body/costume/head/legs outside case and necessary connected wrist/forearm repair exactly unchanged. Do not copy image2 thighs, belt equipment or stance. Retain anatomical-left meter at its original high attachment; carrying gloves may naturally occlude it. No duplicate meter, invented yellow fleck, near-side wrench or metal loop; anatomical-right wrench stays far-side body-occluded. No purple grade, brightening, blur, upscaling aesthetic, new camera or per-pose fitting. Return full square image1 crop with ONLY case/grip correction, transparent background.'''
 pf=p/f'{name}-prompt.txt';pf.write_text(prompt+'\n',encoding='utf-8');files.append(pf)
 data={'preCallSha256':{f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in set(files)},'crop':crop,'admissionRegion':rect,'baseFile':base.name,'references':[f.relative_to(r).as_posix() for f in refs],'scope':'Bounded rigid-case height/contact correction against actual chronological neighbours; provisional standing reference, no body/leg rescale or owner acceptance.'}
 (p/f'{name}-inputs.json').write_text(json.dumps(data,indent=2)+'\n')
print('Three bounded contact repairs prepared with frozen source inventories.')
